export function totalA(items) {
  let sum = 0;
  for (const item of items) {
    if (item.price > 0 && item.qty > 0) {
      sum += item.price * item.qty;
    } else if (item.refund) {
      sum -= item.refund;
    }
  }
  const tax = sum * 0.21;
  return Math.round((sum + tax) * 100) / 100;
}

